#!/usr/bin/env python3
"""Verify the self-signed TLS certificate at /app/ssl/server.crt."""

import os
import ssl
import sys
from datetime import datetime

CERT_PATH = "/app/ssl/server.crt"


def main():
    # Resolve the cert path relative to this script if the absolute path is absent.
    cert_path = CERT_PATH
    if not os.path.exists(cert_path):
        cert_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "ssl", "server.crt")

    # Check 1: certificate file exists
    if not os.path.exists(cert_path):
        print(f"ERROR: certificate not found at {cert_path}")
        sys.exit(1)

    # Check 2: certificate can be loaded/decoded
    try:
        cert = ssl._ssl._test_decode_cert(cert_path)
    except Exception as exc:
        print(f"ERROR: failed to load certificate: {exc}")
        sys.exit(1)

    # Extract the Common Name from the subject
    common_name = None
    organization = None
    for rdn in cert.get("subject", ()):
        for key, value in rdn:
            if key == "commonName":
                common_name = value
            elif key == "organizationName":
                organization = value

    if not common_name:
        print("ERROR: certificate has no Common Name")
        sys.exit(1)

    # Parse the expiration date (OpenSSL format: 'Aug  5 04:12:32 2027 GMT')
    not_after = cert.get("notAfter")
    try:
        expires = datetime.strptime(not_after, "%b %d %H:%M:%S %Y %Z")
    except (TypeError, ValueError) as exc:
        print(f"ERROR: could not parse expiration date: {exc}")
        sys.exit(1)

    print("Certificate details:")
    print(f"  Common Name: {common_name}")
    if organization:
        print(f"  Organization: {organization}")
    print(f"  Expiration date: {expires.strftime('%Y-%m-%d')}")

    print("Certificate verification successful")


if __name__ == "__main__":
    main()
